45	// AddOrUpdateNode adds or updates a node in the network
46	func (n *Network) AddOrUpdateNode(id uint64, h handler, app *App) {
47		n.lock.RLock()
48		node, exists := n.nodes[id]
49		if exists {
50			node.h = h
51			n.lock.RUnlock()
52			return
53		}
54		n.lock.RUnlock()
55	
56		node = &Node{
57			in:                  make(chan msgFrom, incBuffSize),
58			h:                   h,
59			shutdownChan:        make(chan struct{}),
60			n:                   n,
61			id:                  id,
62			peerLossProbability: make(map[uint64]float32),
63			peerMutatingFunc:    make(map[uint64]func(uint64, *smartbftprotos.Message)),
64			app:                 app,
65		}
66		n.lock.Lock()
67		n.nodes[id] = node
68		n.lock.Unlock()
69	
70		node.createCommittedBatches(n)
71	}
