73	// StartServe calls serve on all nodes in the network
74	func (n *Network) StartServe() {
75		n.lock.RLock()
76		defer n.lock.RUnlock()
77		for _, node := range n.nodes {
78			node.running.Add(1)
79			go node.serve()
80		}
81	}
82	
83	// StopServe stops serve for all nodes in the network
84	func (n *Network) StopServe() {
85		n.lock.RLock()
86		defer n.lock.RUnlock()
87		for _, node := range n.nodes {
88			close(node.shutdownChan)
89			node.running.Wait()
90			node.shutdownChan = make(chan struct{}) // reopen for next time
91		}
92	}
93	
94	// Shutdown stops all nodes in the network
95	func (n *Network) Shutdown() {
96		n.lock.RLock()
97		defer n.lock.RUnlock()
98		for _, node := range n.nodes {
99			close(node.shutdownChan)
100			node.running.Wait()
101		}
102		for _, node := range n.nodes {
103			node.h.Stop()
104		}
105	}
