107	func (n *Network) send(source, target uint64, msg proto.Message) {
108		n.lock.RLock()
109		defer n.lock.RUnlock()
110		dstNode, found := n.nodes[target]
111	
112		if !found {
113			panic("node doesn't exist")
114		}
115	
116		srcNode, found := n.nodes[source]
117		if !found {
118			panic("node doesn't exist")
119		}
120	
121		dstNode.probabilityLock.RLock()
122		p := dstNode.lossProbability
123		dstNode.probabilityLock.RUnlock()
124	
125		srcNode.probabilityLock.RLock()
126		q := srcNode.lossProbability
127		w := srcNode.peerLossProbability[target]
128		srcNode.probabilityLock.RUnlock()
129	
130		r := rand.Float32()
131		if r < p || r < q || r < w {
132			return
133		}
134	
135		select {
136		case dstNode.in <- msgFrom{from: int(source), message: msg}:
137		default:
138			fmt.Println("Dropped msg from", source, "to", target, "due to overflow")
139		}
140	}
