176	// Node represents a node in a network
177	type Node struct {
178		sync.RWMutex
179		running             sync.WaitGroup
180		id                  uint64
181		n                   *Network
182		lossProbability     float32
183		peerLossProbability map[uint64]float32
184		syncDelay           <-chan struct{}
185		probabilityLock     sync.RWMutex
186		peerMutatingFunc    map[uint64]func(uint64, *smartbftprotos.Message)
187		mutatingFuncLock    sync.RWMutex
188		shutdownChan        chan struct{}
189		in                  chan msgFrom
190		h                   handler
191		cb                  *committedBatches
192		app                 *App
193	}
194	
195	// SendConsensus sends a consensus related message to a target node
196	func (node *Node) SendConsensus(targetID uint64, m *smartbftprotos.Message) {
197		node.mutatingFuncLock.RLock()
198		mutatingFunc := node.peerMutatingFunc[targetID]
199		msg := m
200		if mutatingFunc != nil {
201			msg = proto.Clone(m).(*smartbftprotos.Message)
202			mutatingFunc(targetID, msg)
203		}
204		node.mutatingFuncLock.RUnlock()
205		node.n.send(node.id, targetID, msg)
206	}
207	
208	// SendTransaction sends a client's request to a target node
209	func (node *Node) SendTransaction(targetID uint64, request []byte) {
210		node.n.send(node.id, targetID, &FwdMessage{Payload: request})
211	}
212	
213	// Nodes returns the ids of all nodes in the network
214	func (node *Node) Nodes() []uint64 {
215		res := node.n.getAll()
216		slices.Sort(res)
217		return res
218	}
219	
220	func (node *Node) serve() {
221		defer node.running.Done()
222		for {
223			select {
224			case <-node.shutdownChan:
225				return
226			case m := <-node.in:
227				node.RLock()
228				handler := node.h
229				node.RUnlock()
230				switch msg := m.message.(type) {
231				case *smartbftprotos.Message:
232					if node.app != nil && node.app.messageLost != nil && node.app.messageLost(msg) {
233						continue
234					}
235					handler.HandleMessage(uint64(m.from), msg)
236				default:
237					handler.HandleRequest(uint64(m.from), msg.(*FwdMessage).Payload)
238				}
239			}
240		}
241	}
242	
243	func (node *Node) createCommittedBatches(network *Network) {
244		ns := network.Nodes()
245		for _, n := range ns {
246			if n.cb != nil {
247				node.cb = n.cb
248				return
249			}
250		}
251		node.cb = &committedBatches{}
252	}
