90	// Sync synchronizes and returns the latest decision
91	func (a *App) Sync() types.SyncResponse {
92		a.Node.probabilityLock.RLock()
93		syncDelay := a.Node.syncDelay
94		a.Node.probabilityLock.RUnlock()
95	
96		if syncDelay != nil {
97			defer func() {
98				<-syncDelay
99				a.Node.probabilityLock.Lock()
100				a.Node.syncDelay = nil
101				a.Node.probabilityLock.Unlock()
102			}()
103		}
104	
105		records := a.Node.cb.readAll(a.latestMD)
106		reconfigSync := types.ReconfigSync{InReplicatedDecisions: false}
107		for _, record := range records {
108			proposal := types.Proposal{
109				Payload:  record.Batch.toBytes(),
110				Metadata: record.Metadata,
111			}
112			a.logger.Debugf("Sync deliver view %d last seq %d", a.latestMD.ViewId, a.latestMD.LatestSequence)
113			a.Deliver(proposal, nil)
114			for _, req := range record.Batch.Requests {
115				request := requestFromBytes(req)
116				if request.Reconfig.InLatestDecision {
117					reconfig := request.Reconfig.recconfigToUint(a.ID)
118					reconfigSync = types.ReconfigSync{
119						InReplicatedDecisions: true,
120						CurrentNodes:          reconfig.CurrentNodes,
121						CurrentConfig:         reconfig.CurrentConfig,
122					}
123				}
124			}
125		}
126		return types.SyncResponse{Latest: *a.lastDecision, Reconfig: reconfigSync}
127	}
