282	// Deliver delivers the given proposal
283	func (a *App) Deliver(proposal types.Proposal, signatures []types.Signature) types.Reconfig {
284		a.lock.Lock()
285		defer a.lock.Unlock()
286		defer func() {
287			a.lastRecord = lastRecord{
288				proposal:   proposal,
289				signatures: signatures,
290			}
291		}()
292		record := &AppRecord{
293			Metadata: proposal.Metadata,
294			Batch:    batchFromBytes(proposal.Payload),
295		}
296		a.Node.cb.add(record)
297		a.lastDecision = &types.Decision{
298			Proposal:   proposal,
299			Signatures: signatures,
300		}
301	
302		prevSeq := a.latestMD.LatestSequence
303	
304		a.latestMD = &smartbftprotos.ViewMetadata{}
305		if err := proto.Unmarshal(proposal.Metadata, a.latestMD); err != nil {
306			panic(err)
307		}
308	
309		a.logger.Debugf("Deliver view %d last seq %d prevSeq %d", a.latestMD.ViewId, a.latestMD.LatestSequence, prevSeq)
310		if prevSeq == a.latestMD.LatestSequence {
311			a.logger.Panicf("Committed sequence %d twice", prevSeq)
312		}
313	
314		a.Delivered <- record
315	
316		for _, req := range record.Batch.Requests {
317			request := requestFromBytes(req)
318			if request.Reconfig.InLatestDecision {
319				reconfig := request.Reconfig.recconfigToUint(a.ID)
320				return types.Reconfig{InLatestDecision: true, CurrentNodes: reconfig.CurrentNodes, CurrentConfig: reconfig.CurrentConfig}
321			}
322		}
323	
324		return types.Reconfig{InLatestDecision: false}
325	}
