333	func (cb *committedBatches) add(record *AppRecord) {
334		cb.lock.Lock()
335		defer cb.lock.Unlock()
336	
337		md := &smartbftprotos.ViewMetadata{}
338		if err := proto.Unmarshal(record.Metadata, md); err != nil {
339			panic(err)
340		}
341	
342		if cb.latestMD != nil && cb.latestMD.ViewId > md.ViewId {
343			return
344		}
345		if cb.latestMD != nil && cb.latestMD.LatestSequence >= md.LatestSequence {
346			return
347		}
348		cb.latestMD = md
349		cb.records = append(cb.records, record)
350	}
351	
352	func (cb *committedBatches) readAll(from *smartbftprotos.ViewMetadata) []*AppRecord {
353		cb.lock.RLock()
354		defer cb.lock.RUnlock()
355	
356		var res []*AppRecord
357		for _, entry := range cb.records {
358			md := &smartbftprotos.ViewMetadata{}
359			if err := proto.Unmarshal(entry.Metadata, md); err != nil {
360				panic(err)
361			}
362			if md.ViewId < from.ViewId || md.LatestSequence <= from.LatestSequence {
363				continue
364			}
365			res = append(res, &AppRecord{
366				Metadata: entry.Metadata,
367				Batch:    entry.Batch,
368			})
369		}
370		return res
371	}
