419	func newNode(id uint64, network *Network, testName string, testDir string, rotateLeader bool, decisionsPerLeader uint64) *App {
420		logConfig := zap.NewDevelopmentConfig()
421		logger, _ := logConfig.Build()
422		logger = logger.With(zap.String("t", testName)).With(zap.Int64("id", int64(id)))
423		sugaredLogger := logger.Sugar()
424	
425		app := &App{
426			clock:           time.NewTicker(time.Second),
427			secondClock:     time.NewTicker(time.Second),
428			ID:              id,
429			Delivered:       make(chan *AppRecord, 100),
430			logLevel:        logConfig.Level,
431			latestMD:        &smartbftprotos.ViewMetadata{},
432			lastDecision:    &types.Decision{},
433			logger:          sugaredLogger,
434			metricsProvider: &disabled.Provider{},
435		}
